const marker = () => () => {}

export const Controller = marker
export const Get = marker
export const Settings = marker
export const Value = marker
export const Guard = marker

export class Logger {
  constructor(lines = []) {
    this.lines = lines
  }
  info(message) {
    this.lines.push(message)
  }
}

export const coerce = {
  number(value, label) {
    const number = Number(value)
    if (value === undefined || Number.isNaN(number)) {
      throw new Error(`invalid ${label}`)
    }
    return number
  },
}

export function build(Class, logger, fields) {
  const instance = new Class()
  for (const field of fields) {
    if ('default' in field) {
      instance[field.property] = field.default
    }
  }
  logger.info(`built ${Class.name}`)
  return instance
}
